 Проблема до дженериков До Go 1.18 универсальный код писали через any (interface{}), теряя типобезопасность, или через кодогенерацию.
// без дженериков — unsafe func MaxAny(a, b any) any { // нельзя сравнить без type switch } Синтаксис дженериков Параметры типа указываются в квадратных скобках:
func Max[T int | float64 | string](a, b T) T { if a &gt; b { return a } return b } fmt.Println(Max(3, 5)) // 5 fmt.Println(Max(3.14, 2.71)) // 3.14 fmt.Println(Max(&#34;ab&#34;, &#34;ac&#34;)) // ac Дженерик-тип Параметры типа работают и для определений типов:
type Stack[T any] struct { items []T } func (s *Stack[T]) Push(v T) { s.items = append(s.items, v) } func (s *Stack[T]) Pop() (T, bool) { if len(s.items) == 0 { var zero T return zero, false } v := s.items[len(s.items)-1] s.items = s.items[:len(s.items)-1] return v, true } s := Stack[int]{} s.Push(1) s.Push(2) v, _ := s.Pop() // 2 Упражнения № Задание Сложность 1 Упражнение 1 easy 2 Упражнение 2 medium

 Внутренняя структура среза ┌─────────┬─────┬─────┐ │ *array │ len │ cap │ └─────────┴─────┴─────┘ │ ▼ ┌────┬────┬────┬────┬────┐ │ 10 │ 20 │ 30 │ 40 │ 50 │ └────┴────┴────┴────┴────┘ len — количество доступных элементов. cap — размер выделенного массива от начала среза до конца. Рост при append Когда len == cap, append выделяет новый массив и копирует данные:
s := make([]int, 0) for i := 0; i &lt; 8; i++ { prev := cap(s) s = append(s, i) if cap(s) != prev { fmt.Printf(&#34;len=%d cap: %d → %d\n&#34;, len(s), prev, cap(s)) } } // cap: 0→1, 1→2, 2→4, 4→8 Стратегия удвоения даёт амортизированную стоимость O(1) на один append.
Предвыделение Если конечный размер известен — выделяй сразу:
// Плохо: многократное копирование var result []int for _, v := range source { result = append(result, transform(v)) } // Хорошо: одна аллокация result := make([]int, 0, len(source)) for _, v := range source { result = append(result, transform(v)) } copy src := []int{1, 2, 3, 4, 5} dst := make([]int, 3) n := copy(dst, src) // копирует min(len(dst), len(src)) элементов fmt.Println(dst, n) // [1 2 3] 3 Утечки памяти через срезы Подсрез держит ссылку на весь исходный массив:
// Утечка: большой массив не будет собран GC data := readBigFile() header := data[:10] // data остаётся в памяти // Исправление: явная копия header := make([]byte, 10) copy(header, data[:10]) Упражнения № Задание Сложность 1 Упражнение 1 easy 2 Упражнение 2 easy 3 Упражнение 3 medium

 По умолчанию — копия Go передаёт аргументы в функции по значению: функция получает копию, а не оригинал.
func double(x int) { x *= 2 // изменяет только копию } n := 5 double(n) fmt.Println(n) // 5 — не изменилось Передача указателя Чтобы функция могла изменить переменную вызывающего кода, передают адрес:
func double(x *int) { *x *= 2 } n := 5 double(&amp;n) fmt.Println(n) // 10 Срезы и карты — ссылочные типы Срез ([]T) и карта (map[K]V) внутри содержат указатель на данные. При передаче в функцию копируется заголовок (pointer + len + cap), но данные — общие:
func fill(s []int) { s[0] = 99 // изменяет исходный массив } a := []int{1, 2, 3} fill(a) fmt.Println(a) // [99 2 3] Однако append может создать новый массив — изменения тогда не видны снаружи. Если нужно изменить сам срез (длину), передают *[]int.
Упражнения № Задание Сложность 1 Упражнение 1 easy 2 Упражнение 2 easy 3 Упражнение 3 medium

 Обходы в глубину (DFS) Три варианта — отличаются порядком обработки узла относительно его поддеревьев.
// Pre-order: корень → левое → правое func preOrder[T any](n *TreeNode[T], fn func(T)) { if n == nil { return } fn(n.Value) preOrder(n.Left, fn) preOrder(n.Right, fn) } // In-order: левое → корень → правое (для BST даёт отсортированный порядок) func inOrder[T any](n *TreeNode[T], fn func(T)) { if n == nil { return } inOrder(n.Left, fn) fn(n.Value) inOrder(n.Right, fn) } // Post-order: левое → правое → корень (удаление дерева, вычисление выражений) func postOrder[T any](n *TreeNode[T], fn func(T)) { if n == nil { return } postOrder(n.Left, fn) postOrder(n.Right, fn) fn(n.Value) } Итеративный in-order (без рекурсии) func inOrderIterative[T any](root *TreeNode[T]) []T { var result []T var stack []*TreeNode[T] cur := root for cur != nil || len(stack) &gt; 0 { for cur != nil { stack = append(stack, cur); cur = cur.Left } cur = stack[len(stack)-1] stack = stack[:len(stack)-1] result = append(result, cur.Value) cur = cur.Right } return result } Обход в ширину (BFS / Level-order) Обходит дерево уровень за уровнем, используя очередь:
func bfs[T any](root *TreeNode[T], fn func(T)) { if root == nil { return } queue := []*TreeNode[T]{root} for len(queue) &gt; 0 { node := queue[0] queue = queue[1:] fn(node.Value) if node.Left != nil { queue = append(queue, node.Left) } if node.Right != nil { queue = append(queue, node.Right) } } } Применения Обход Применение Pre-order Копирование дерева, сериализация In-order Отсортированный вывод BST, range queries Post-order Удаление дерева, вычисление арифметических выражений BFS Кратчайший путь, уровни дерева, is-balanced Упражнения № Задание Сложность 1 Упражнение 1 easy 2 Упражнение 2 easy 3 Упражнение 3 medium 4 Упражнение 4 medium

 Предвыделение памяти Если размер известен — задай начальную ёмкость через make:
// Без подсказки — многократное перехеширование при росте m := make(map[string]int) // С подсказкой — меньше аллокаций m := make(map[string]int, 10000) Подсказка не ограничивает размер, только уменьшает количество перехеширований.
Ключи и их стоимость Стоимость хеширования зависит от типа ключа:
Тип ключа Стоимость хеширования int минимальная string O(len) struct O(полей) interface дополнительный boxing Для горячих путей используй числовые ключи вместо строковых:
// Медленнее: хеширование строки cache := map[string]*Result{} // Быстрее: хеширование числа type UserID uint64 cache := map[UserID]*Result{} Альтернативы map для специальных случаев // Маленькие наборы (n &lt; 10) — линейный поиск по срезу быстрее из-за кэша type KV struct{ K, V string } table := []KV{{&#34;a&#34;, &#34;1&#34;}, {&#34;b&#34;, &#34;2&#34;}} // Счётчики с ограниченным диапазоном — массив var freq [256]int for _, c := range text { freq[c]++ } // Битовый массив для наличия/отсутствия var seen [1 &lt;&lt; 16]bool Профилирование import &#34;runtime&#34; var before, after runtime.MemStats runtime.ReadMemStats(&amp;before) // ... операции с map ... runtime.ReadMemStats(&amp;after) fmt.Println(&#34;allocs:&#34;, after.Mallocs-before.Mallocs) Для бенчмарков используй testing.B:
func BenchmarkMap(b *testing.B) { m := make(map[int]int, b.N) for i := 0; i &lt; b.N; i++ { m[i] = i } } Упражнения № Задание Сложность 1 Упражнение 1 easy 2 Упражнение 2 easy 3 Упражнение 3 medium
